<span class="line"><span class="token keyword">record</span> <span class="token class-name">SearchResult</span><span class="token punctuation">(</span><span class="token class-name"><span class="token keyword">string</span></span> Title<span class="token punctuation">,</span> <span class="token class-name"><span class="token keyword">string</span></span> Url<span class="token punctuation">,</span> <span class="token class-name"><span class="token keyword">double</span></span> Distance<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
